#include<bits/stdc++.h>using namespace std; int main(){    int n,k;    cin >> n >> k;    vector<int> a(n);    for(int i=0;i<n;i++)    {        cin >> a[i];    }    sort(a.begin(),a.end());    long long sum =0;    for(int i=0;i<n && k>0;i++)    {        if(a[i] < 0)        {             sum = sum + abs(a[i]);             k--;        }    }    cout << sum << endl;}